#include <bits/stdc++.h>
using namespace std;
const int MOD = 998244353;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    string S;
    cin >> N >> S;

    // dp[j] = ways to have current Snuke still holding j balls
    vector<long long> dp(3, 0);
    dp[0] = 1;

    for (int i = 0; i < N; i++) {
        vector<long long> ndp(3, 0);
        int type = S[i] - '0';
        for (int j = 0; j <= 2; j++) {
            if (dp[j] == 0) continue;
            // j balls already held from previous Snuke, plus 2 new from current Snuke
            int total = j + 2;
            if (type == 0) {
                // 2 red balls, indistinguishable
                // possible handoffs: give 0,1,2 balls to Takahashi from current Snuke
                for (int give = 0; give <= min(total, 2); give++) {
                    int keep = total - give;
                    if (keep > 2) continue;
                    // ways to choose which balls to give: all red so 1 way
                    ndp[keep] = (ndp[keep] + dp[j]) % MOD;
                }
            } else if (type == 1) {
                // 1 red, 1 blue distinguishable
                for (int give = 0; give <= min(total, 2); give++) {
                    int keep = total - give;
                    if (keep > 2) continue;
                    // ways = C(total, give) but balls are now distinguishable
                    // Actually we have total balls, some may be from previous carry
                    // We need to count ways to select `give` balls from `total`
                    // total <= 4, so we can precompute small combinations
                    long long ways = 0;
                    if (give == 0) ways = 1;
                    else if (give == 1) ways = total;
                    else if (give == 2) ways = total * (total - 1) / 2;
                    ndp[keep] = (ndp[keep] + dp[j] * ways) % MOD;
                }
            } else { // type == 2
                // 2 blue balls, indistinguishable
                for (int give = 0; give <= min(total, 2); give++) {
                    int keep = total - give;
                    if (keep > 2) continue;
                    ndp[keep] = (ndp[keep] + dp[j]) % MOD;
                }
            }
        }
        swap(dp, ndp);
    }

    // After last Snuke, all balls must be handed to Takahashi -> 0 balls remaining
    cout << dp[0] % MOD << "\n";
    return 0;
}

