using namespace std;

static const long long MOD = 998244353;

// modpow
long long modpow(long long a, long long e) {
    long long r = 1;
    while (e > 0) {
        if (e & 1) r = r * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return r;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    string S;
    cin >> N >> S;

    // Let R_i be the number of red balls among first i Snukes initially.
    // For any achievable final Takahashi sequence, at every prefix t,
    // #red among first t outputs must lie between:
    //   max(0, t - B_i) and min(t, R_i) for every i with t<=2i,
    // which simplifies to the path condition of a lattice path staying
    // within intervals.
    //
    // A standard transformation gives:
    // define x_i = (#red among first i outputs).
    // Then x_i - x_{i-1} is 0/1 depending on output color.
    //
    // Feasibility is equivalent to:
    // for each prefix length k, x_k must satisfy
    //   L_k <= x_k <= U_k
    // where
    //   U_k = min over i>=ceil(k/2) of R_i and also <=k
    //   L_k = max over i>=ceil(k/2) of (k - B_i) = k - max over i>=ceil(k/2) B_i
    //
    // Since R_i is nondecreasing and B_i = 2i - R_i, these become:
    //   U_k = R_{ceil(k/2)}
    //   L_k = k - B_{ceil(k/2)} = R_{ceil(k/2)} - (2*ceil(k/2)-k)
    //
    // Therefore:
    //   for k=2m:   x_{2m} = R_m
    //   for k=2m-1: x_{2m-1} is either R_m-1 or R_m
    //
    // Hence each pair of consecutive outputs corresponding to m:
    // among first 2m outputs, exactly R_m reds;
    // among first 2m-1 outputs, reds can be R_m-1 or R_m.
    //
    // This means outputs in positions (2m-1, 2m) are:
    //   RR if S[m]='0'
    //   RB or BR if S[m]='1'
    //   BB if S[m]='2'
    //
    // Different m are independent, so answer is 2^(count of '1').

    int cnt1 = 0;
    for (char c : S) if (c == '1') cnt1++;

    cout << modpow(2, cnt1) << '\n';
    return 0;
}

