public class Main {
    static final long MOD = 998244353L;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int N = fs.nextInt();
        String S = fs.next();

        // dp[a][b][c]:
        // after processing some prefix of Snukes from front to back,
        // the set of possible Takahashi sequences for that prefix is represented
        // by counts of remaining balls passed from the last processed Snuke to the next:
        // a = number of red balls among the 2 balls currently at boundary already fixed in order prefix
        //
        // More conveniently, we derive a compact DP on counts of possible prefixes.
        //
        // Let dp[x][y] = number of distinct sequences obtainable from processed snukes
        // such that among balls currently waiting to be output from the next boundary,
        // there are x red and y blue balls (x+y <= 2).
        //
        // Since each snuke has total 2 balls, boundary state size is at most 2.
        //
        // Transition:
        // incoming boundary has x red and y blue balls from behind previous snuke.
        // current snuke has cr red and cb blue initially.
        // total available = x+cr red, y+cb blue, total 2 + x+y.
        // current snuke must pass exactly min(2, total) balls forward over two rounds?
        //
        // A cleaner characterization:
        // After all 2N simultaneous rounds, the relative order constraints are exactly:
        // each snuke's 2 output balls are formed by interleaving its own initial 2 balls
        // with the 2 balls received from behind, preserving received order.
        //
        // Therefore we process from back to front:
        // F_i = set of possible sequences of balls ultimately emitted by snuke i to i-1/Takahashi,
        // obtained by merging the fixed local multiset (2 balls of snuke i) with a sequence from F_{i+1},
        // taking exactly first 2 emitted onward? This still needs careful handling.
        //
        // Instead, use direct combinational DP on counts of red prefixes.
        //
        // Key observation:
        // In each round, a snuke can send at most one ball, so each snuke's two original balls
        // leave in some order, but between them at most one received ball can be inserted before
        // first original, between originals, and after originals recursively. This is equivalent
        // to saying the final Takahashi sequence is any sequence obtainable by repeatedly replacing
        // each symbol i by a merge of its local 2-ball string with the sequence from i+1, preserving
        // order of the latter. This leads to simple DP on number of reds after each block.
        //
        // More concretely, let dp[r] = number of ways to obtain a sequence of length 2*k
        // from first k snukes with exactly r reds, but we need distinct sequences, not ways.
        // Distinctness only depends on binary string, so count reachable binary strings.
        //
        // Reachable set from adding one snuke with t red balls (t in {0,1,2}) to front of an existing
        // reachable binary string U (length 2m) is all strings formed by inserting t zeros and 2-t ones
        // into U under the queueing constraint. This turns out exactly all strings where the subsequence U
        // remains after deleting two chars, because front snuke can output its balls at any two positions
        // relative to downstream outputs. Hence transition on languages:
        // new set = all supersequences by inserting local 2-char string as an ordered subsequence.
        //
        // Therefore counting distinct resulting strings can be done by DP over number of reds:
        // from each reachable string, inserting:
        // 00 -> choose positions of two 0s preserving all else
        // 01/10 but local order for type 1 can be either RB or BR? Since one red and one blue,
        // snuke may choose either first, so local 2-char string can be 01 or 10.
        // 11 similarly.
        //
        // After closure over all reachable strings, the set depends only on total number of reds:
        // every binary string with that many reds is reachable.
        // Proof by induction: inserting 00/11/01/10 into any binary string can generate all binary strings
        // with updated red count.
        //
        // Thus answer is simply C(2N, totalRed).
        int totalRed = 0;
        for (int i = 0; i < N; i++) {
            char ch = S.charAt(i);
            if (ch == '0') totalRed += 2;
            else if (ch == '1') totalRed += 1;
        }

        Comb comb = new Comb(2 * N, MOD);
        System.out.println(comb.nCk(2 * N, totalRed));
    }

    static class Comb {
        long[] fact, invFact;
        int n;
        long mod;

        Comb(int n, long mod) {
            this.n = n;
            this.mod = mod;
            fact = new long[n + 1];
            invFact = new long[n + 1];
            fact[0] = 1;
            for (int i = 1; i <= n; i++) fact[i] = fact[i - 1] * i % mod;
            invFact[n] = modPow(fact[n], mod - 2, mod);
            for (int i = n; i >= 1; i--) invFact[i - 1] = invFact[i] * i % mod;
        }

        long nCk(int n, int k) {
            if (k < 0 || k > n) return 0;
            return fact[n] * invFact[k] % mod * invFact[n - k] % mod;
        }

        static long modPow(long a, long e, long mod) {
            long r = 1;
            while (e > 0) {
                if ((e & 1) == 1) r = r * a % mod;
                a = a * a % mod;
                e >>= 1;
            }
            return r;
        }
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MOD 998244353LL

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    char *S = (char *)malloc((N + 5) * sizeof(char));
    scanf("%s", S);

    /*
      Let dp[a][b] = number of possible resulting sequences after processing
      current prefix of Snukes, where:
        a = #red balls passed to the next Snuke (to the front side)
        b = #blue balls passed to the next Snuke
      Since each Snuke passes exactly all balls he has over time, and each Snuke
      initially has 2 balls, after processing i Snukes, a+b = 2*i - (#balls already
      output to Takahashi from these i Snukes). But we can just keep both counts.

      Transition for one Snuke:
      He receives a red/blue multiset (a,b) from behind, plus his own initial balls.
      Suppose his own balls are (sr,sb).
      Total balls he must send forward/output are:
        R = a + sr
        B = b + sb
      Among all interleavings of these R+B balls preserving colors only, every choice
      corresponds to a possible sequence of balls output by this Snuke to the front
      (eventually Takahashi for the first one in processed order). The next state
      after processing this Snuke is simply (R,B).
      Therefore, multiplying by C[R+B][R].

      Processing from back to front:
      start dp[0][0] = 1.
      For each Snuke, newdp[R][B] += dp[a][b] * C[R+B][R], where R=a+sr, B=b+sb.

      At the end, after processing all N Snukes, the first Snuke outputs all remaining
      balls to Takahashi, so answer is dp[finalR][finalB], summed over states.
      But total reds/blues are fixed by S, and transitions are deterministic in state,
      so actually only one final state exists. Still summing is fine.

      Since each step only shifts by at most 2, states satisfy a+b = 2*i.
      We can compress to 1D by red count only.
    */

    int maxBalls = 2 * N;

    long long *fact = (long long *)malloc((maxBalls + 1) * sizeof(long long));
    long long *invfact = (long long *)malloc((maxBalls + 1) * sizeof(long long));

    fact[0] = 1;
    for (int i = 1; i <= maxBalls; i++) fact[i] = fact[i - 1] * i % MOD;

    long long base = fact[maxBalls], exp = MOD - 2, res = 1;
    while (exp) {
        if (exp & 1) res = res * base % MOD;
        base = base * base % MOD;
        exp >>= 1;
    }
    invfact[maxBalls] = res;
    for (int i = maxBalls; i >= 1; i--) invfact[i - 1] = invfact[i] * i % MOD;

    long long *dp = (long long *)calloc(maxBalls + 1, sizeof(long long));
    long long *ndp = (long long *)calloc(maxBalls + 1, sizeof(long long));
    dp[0] = 1;

    int totalRed = 0;

    for (int i = N - 1; i >= 0; i--) {
        int sr = 0, sb = 0;
        if (S[i] == '0') { sr = 2; sb = 0; }
        else if (S[i] == '1') { sr = 1; sb = 1; }
        else { sr = 0; sb = 2; }

        int processedBehind = 2 * (N - 1 - i);

        for (int r = 0; r <= processedBehind + 2; r++) ndp[r] = 0;

        for (int r = 0; r <= processedBehind; r++) {
            long long cur = dp[r];
            if (!cur) continue;
            int b = processedBehind - r;

            int R = r + sr;
            int B = b + sb;
            int T = R + B;

            long long ways = fact[T] * invfact[R] % MOD * invfact[B] % MOD;
            ndp[R] = (ndp[R] + cur * ways) % MOD;
        }

        for (int r = 0; r <= processedBehind + 2; r++) dp[r] = ndp[r];
        totalRed += sr;
    }

    printf("%lld\n", dp[totalRed] % MOD);

    free(S);
    free(fact);
    free(invfact);
    free(dp);
    free(ndp);
    return 0;
}

